DO $$ DECLARE t_id uuid; s_id uuid; q_id uuid; BEGIN
  INSERT INTO public.evaluation_templates (program_id, name, title_en, status, status_enum, version_label, source_document_id, extraction_confidence, needs_review)
  SELECT sd.program_id, convert_from(decode('e0b8abe0b8a5e0b8b1e0b881e0b8aae0b8b9e0b895e0b8a3e0b8a7e0b8b4e0b897e0b8a2e0b8b2e0b8a8e0b8b2e0b8aae0b895e0b8a3e0b89ae0b8b1e0b893e0b891e0b8b4e0b895e0b8aae0b8b2e0b882e0b8b2e0b8ade0b899e0b8b2e0b8a1e0b8b1e0b8a2e0b8aae0b8b4e0b988e0b887e0b981e0b8a7e0b894e0b8a5e0b989e0b8ade0b8a1', 'hex'), 'utf8'), '(Sustainable development)', 'draft', 'draft'::assessment_status, '0.1', sd.id, 0.82, true
  FROM public.assessment_source_documents sd WHERE sd.filename = convert_from(decode('', 'hex'), 'utf8')
  RETURNING id INTO t_id;
  IF t_id IS NULL THEN RETURN; END IF;
  INSERT INTO public.assessment_sections (template_id, title_th, title_en, domain_type, sequence)
  VALUES (t_id, convert_from(decode('e0b894e0b989e0b8b2e0b899e0b8a5e0b8b1e0b881e0b8a9e0b893e0b8b0e0b89ae0b8b8e0b884e0b884e0b8a5', 'hex'), 'utf8'), NULL, 'character'::domain_type, 1)
  RETURNING id INTO s_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, convert_from(decode('', 'hex'), 'utf8'), NULL, 'PLO1', 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, convert_from(decode('', 'hex'), 'utf8'), NULL, 'PLO2', 'single_choice'::question_type, true, 2)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, convert_from(decode('e0b89be0b989e0b8ade0b887e0b881e0b8b1e0b899e0b981e0b8a5e0b8b0e0b884e0b8a7e0b89ae0b884e0b8b8e0b8a1e0b89be0b8b1e0b888e0b888e0b8b1e0b8a2e0b980e0b8aae0b8b5e0b988e0b8a2e0b887e0b895e0b988e0b8ade0b8aae0b8b8e0b882e0b8a0e0b8b2e0b89ee0b8a1e0b899e0b8b8e0b8a9e0b8a2e0b98c', 'hex'), 'utf8'), NULL, 'PLO3', 'single_choice'::question_type, true, 3)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, convert_from(decode('', 'hex'), 'utf8'), NULL, 'PLO4', 'single_choice'::question_type, true, 4)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, convert_from(decode('', 'hex'), 'utf8') || convert_from(decode('e0b988e0b8a1e0b8b5e0b89ce0b8a5e0b895e0b988e0b8ade0b8aae0b8b8e0b882e0b8a0e0b8b2e0b89e', 'hex'), 'utf8'), NULL, 'PLO5', 'single_choice'::question_type, true, 5)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, convert_from(decode('e0b8aae0b8b7e0b988e0b8ade0b8aae0b8b2e0b8a3e0b884e0b8a7e0b8b2e0b8a1e0b980e0b8aae0b8b5e0b988e0b8a2e0b887e0b894e0b989e0b8b2e0b899e0b8ade0b899e0b8b2e0b8a1e0b8b1e0b8a2e0b8aae0b8b4e0b988e0b887e0b981e0b8a7e0b894e0b8a5e0b989e0b8ade0b8a1', 'hex'), 'utf8'), NULL, 'PLO6', 'single_choice'::question_type, true, 6)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, convert_from(decode('', 'hex'), 'utf8')
    || convert_from(decode('', 'hex'), 'utf8')
    || convert_from(decode('', 'hex'), 'utf8')
    || convert_from(decode('', 'hex'), 'utf8')
    || convert_from(decode('', 'hex'), 'utf8')
    || convert_from(decode('', 'hex'), 'utf8')
    || convert_from(decode('', 'hex'), 'utf8')
    || convert_from(decode('', 'hex'), 'utf8')
    || convert_from(decode('', 'hex'), 'utf8')
    || convert_from(decode('', 'hex'), 'utf8')
    || convert_from(decode('', 'hex'), 'utf8')
